* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.shell { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #e2e7ef; border-radius: 12px; box-shadow: 0 8px 30px #1720330b; }
h1 { margin: 0 0 28px; font-size: 2rem; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; padding: 10px 12px; border: 1px solid #b8c1d0; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315bd6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #2449b7; }
button:focus-visible, input:focus-visible { outline: 3px solid #95b2ff; outline-offset: 2px; }
.alert { grid-column: 1 / -1; margin: 0; color: #b42318; }
.alert[hidden] { display: none; }
.project-list { margin-top: 24px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e2e7ef; }
@media (max-width: 600px) { .shell { margin: 20px 12px; padding: 22px; } .create-form { grid-template-columns: 1fr; } .create-form label, .alert { grid-column: auto; } }

