import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import path from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);

const root = path.resolve('public');
const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(body);
};
const json = (res, status, data) => send(res, status, JSON.stringify(data));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);
  if (req.method === 'GET' && url.pathname === '/health') return json(res, 200, { status: 'ok' });

  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, db.prepare('SELECT id, name FROM projects ORDER BY id').all());
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let body = '';
    for await (const chunk of req) body += chunk;
    let data;
    try { data = JSON.parse(body); } catch { return json(res, 400, { error: 'Invalid JSON' }); }
    const name = typeof data.name === 'string' ? data.name.trim() : '';
    if (!name) return json(res, 400, { error: 'Project name is required' });
    const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
    return json(res, 201, { id: Number(result.lastInsertRowid), name });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && req.method === 'GET') {
    const project = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? json(res, 200, project) : json(res, 404, { error: 'Not found' });
  }

  if (req.method === 'GET') {
    const file = url.pathname === '/' ? 'index.html' : url.pathname.slice(1);
    if (!file.includes('..') && !file.includes('/')) {
      try {
        const content = await readFile(path.join(root, file));
        const type = file.endsWith('.js') ? 'text/javascript; charset=utf-8' : file.endsWith('.css') ? 'text/css; charset=utf-8' : 'text/html; charset=utf-8';
        return send(res, 200, content, type);
      } catch {}
    }
    // Client-side project routes share the same entry point.
    if (/^\/projects\/\d+\/?$/.test(url.pathname)) {
      try { return send(res, 200, await readFile(path.join(root, 'index.html')), 'text/html; charset=utf-8'); } catch {}
    }
  }
  json(res, 404, { error: 'Not found' });
});

server.listen(port, '0.0.0.0', () => console.log(`Workboard listening on ${port}`));
process.on('SIGINT', () => { server.close(); db.close(); });
process.on('SIGTERM', () => { server.close(); db.close(); });

const app = document.querySelector('#app');

async function request(url, options) {
  const response = await fetch(url, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Request failed');
  return data;
}

function heading(text) {
  const h = document.createElement('h1');
  h.textContent = text;
  return h;
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) {
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.append(heading(project.name));
    } catch {
      app.append(heading('Project not found'));
    }
    const back = document.createElement('button');
    back.type = 'button';
    back.textContent = 'Projects';
    back.addEventListener('click', () => navigate('/'));
    app.append(back);
    return;
  }

  app.append(heading('Workboard'));
  const form = document.createElement('form');
  form.className = 'create-form';
  const label = document.createElement('label');
  label.htmlFor = 'project-name';
  label.textContent = 'Project name';
  const input = document.createElement('input');
  input.id = 'project-name';
  input.name = 'projectName';
  input.type = 'text';
  const button = document.createElement('button');
  button.type = 'submit';
  button.textContent = 'Create project';
  const alert = document.createElement('p');
  alert.className = 'alert';
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  form.append(label, input, button, alert);
  app.append(form);

  const list = document.createElement('section');
  list.className = 'project-list';
  list.setAttribute('aria-label', 'Projects');
  app.append(list);
  const projects = await request('/api/projects');
  for (const project of projects) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    row.append(name, open);
    list.append(row);
  }
  form.addEventListener('submit', async event => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    try {
      await request('/api/projects', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) });
      render();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    }
  });
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}
window.addEventListener('popstate', render);
render();

* { box-sizing: border-box; }
body { margin: 0; background: #f5f7fb; color: #172033; font: 16px/1.5 system-ui, sans-serif; }
.shell { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border: 1px solid #e2e7ef; border-radius: 12px; box-shadow: 0 8px 30px #1720330b; }
h1 { margin: 0 0 28px; font-size: 2rem; }
.create-form { display: grid; grid-template-columns: 1fr auto; gap: 8px 12px; align-items: center; }
.create-form label { grid-column: 1 / -1; font-weight: 600; }
input { min-width: 0; padding: 10px 12px; border: 1px solid #b8c1d0; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 0; border-radius: 6px; background: #315bd6; color: white; font: inherit; font-weight: 600; cursor: pointer; }
button:hover { background: #2449b7; }
button:focus-visible, input:focus-visible { outline: 3px solid #95b2ff; outline-offset: 2px; }
.alert { grid-column: 1 / -1; margin: 0; color: #b42318; }
.alert[hidden] { display: none; }
.project-list { margin-top: 24px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 14px 0; border-top: 1px solid #e2e7ef; }
@media (max-width: 600px) { .shell { margin: 20px 12px; padding: 22px; } .create-form { grid-template-columns: 1fr; } .create-form label, .alert { grid-column: auto; } }

